export function wrapSimplePattern(
	data: T.SimplePattern & { readonly $other?: T.SimplePattern | readonly T.SimplePattern[] },
	tree: TreeHandle
) {
	if (typeof data === 'number') return data;
	data = _keepModelledSlots(data, [
		'_class_pattern',
		'_splat_pattern',
		'_union_pattern',
		'_case_list_pattern',
		'_case_tuple_pattern',
		'_dict_pattern',
		'_string',
		'_concatenated_string',
		'_true',
		'_false',
		'_none',
		'__simple_pattern_negative',
		'_simple_pattern_negative',
		'_complex_pattern',
		'_dotted_name',
		'__wildcard_pattern',
		'_wildcard_pattern'
	]);
	const kindKeyed = _firstKindKeyedWrapChild(data, [
		'class_pattern',
		'splat_pattern',
		'union_pattern',
		'case_list_pattern',
		'case_tuple_pattern',
		'dict_pattern',
		'string',
		'concatenated_string',
		'true',
		'false',
		'none',
		'_simple_pattern_negative',
		'simple_pattern_negative',
		'complex_pattern',
		'dotted_name',
		'_wildcard_pattern',
		'wildcard_pattern'
	]) as T.SimplePattern | readonly T.SimplePattern[] | undefined;
	const filtered =
		kindKeyed ??
		_filterWrapChildrenByKind(data.$other, [
			'class_pattern',
			'splat_pattern',
			'union_pattern',
			'case_list_pattern',
			'case_tuple_pattern',
			'dict_pattern',
			'string',
			'concatenated_string',
			'true',
			'false',
			'none',
			'_simple_pattern_negative',
			'simple_pattern_negative',
			'complex_pattern',
			'dotted_name',
			'_wildcard_pattern',
			'wildcard_pattern'
		]);
	if (filtered === undefined && typeof (data as _NodeData).$text === 'string') {
		return drillInSelf<T.SimplePattern>(data as T.SimplePattern, tree);
	}
	return drillIn<T.SimplePattern>(
		normalizeSingularWrapSlot(filtered, 'children', true, data.$type, {
			tree,
			nodeType: data.$type,
			slotName: 'children',
			span: (data as _NodeData).$span
		}),
		tree
	);
}

